            zy_below = sy + 5
            if 2 <= zy_below <= 97:
                t2 = (t + 1) % 3
                if t2 == 0:
                    zt2 = Tool.RESIDENTIAL
                elif t2 == 1:
                    zt2 = Tool.COMMERCIAL
                else:
                    zt2 = Tool.INDUSTRIAL
                plan.append((zt2, zx, zy_below))

    # Place coal plants LAST so they aren't bulldozed
