def build_plan():
    plan = []

    # Strategy: Compact neighborhood clusters with direct power plant adjacency
    # Each cluster: power plant at center, surrounded by zones, roads around perimeter
    # Wire connects clusters together

    # Cluster layout: power plant at center of a 7x7 block
    # Zones (3x3) placed adjacent to power plant (sharing edge = powered)
    # Roads run along the outer edge of each cluster

    # Cluster centers (power plant positions) - spaced 14 apart
    cluster_centers = []
    for cy in range(15, 90, 18):
        for cx in range(15, 110, 18):
            cluster_centers.append((cx, cy))

    # Place a coal power plant at each cluster center
    for (cx, cy) in cluster_centers:
        plan.append((Tool.COALPOWER, cx, cy))

    # Connect all power plants with wire (horizontal then vertical backbone)
    # Horizontal wire at y=15 connecting all plants in that row
    wire_ys = list(set(cy for (cx, cy) in cluster_centers))
    wire_xs = list(set(cx for (cx, cy) in cluster_centers))

    for wy in wire_ys:
        for wx in range(min(wire_xs)-2, max(wire_xs)+3):
            plan.append((Tool.WIRE, wx, wy))

    # Vertical wire connecting rows
    for wx in wire_xs:
        for wy in range(min(wire_ys)-2, max(wire_ys)+3):
            plan.append((Tool.WIRE, wx, wy))

    # For each cluster, place zones around the power plant
    # Power plant is 4x4 (placed at center cell), zones are 3x3
    # Place zones at offsets: N, S, E, W, NE, NW, SE, SW of power plant
    # Zone center must be 4 away from plant center to not overlap
    zone_offsets = [
        (-5, 0), (5, 0), (0, -5), (0, 5),
        (-5, -5), (5, -5), (-5, 5), (5, 5),
    ]
    zone_types_cycle = [
        Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL,
        Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL,
    ]

    for (cx, cy) in cluster_centers:
        for i, (dx, dy) in enumerate(zone_offsets):
            zx = cx + dx
            zy = cy + dy
            if 2 <= zx <= 117 and 2 <= zy <= 97:
                tool = zone_types_cycle[i % len(zone_types_cycle)]
                plan.append((tool, zx, zy))

    # Add roads connecting zones to each other around each cluster
    # Road ring around each cluster at radius ~8
    for (cx, cy) in cluster_centers:
        # Horizontal roads above and below cluster
        for rx in range(cx - 8, cx + 9):
            if 0 <= rx < WORLD_W:
                if 0 <= cy - 8 < WORLD_H:
                    plan.append((Tool.ROAD, rx, cy - 8))
                if 0 <= cy + 8 < WORLD_H:
                    plan.append((Tool.ROAD, rx, cy + 8))
        # Vertical roads left and right of cluster
        for ry in range(cy - 8, cy + 9):
            if 0 <= ry < WORLD_H:
                if 0 <= cx - 8 < WORLD_W:
                    plan.append((Tool.ROAD, cx - 8, ry))
                if 0 <= cx + 8 < WORLD_W:
                    plan.append((Tool.ROAD, cx + 8, ry))

    # Add inter-cluster roads connecting horizontally adjacent clusters
    for (cx, cy) in cluster_centers:
        # Find right neighbor
        right_cx = cx + 18
        if right_cx <= max(wire_xs):
            for rx in range(cx + 9, right_cx - 8):
                if 0 <= rx < WORLD_W and 0 <= cy < WORLD_H:
                    plan.append((Tool.ROAD, rx, cy + 8))

    # Add fire and police stations for service coverage
    service_positions = []
    for (cx, cy) in cluster_centers[::3]:
        service_positions.append((Tool.FIRESTATION, cx - 2, cy + 2))
    for (cx, cy) in cluster_centers[1::3]:
        service_positions.append((Tool.POLICESTATION, cx + 2, cy - 2))

    for s in service_positions:
        tool, sx, sy = s
        if 0 <= sx < WORLD_W and 0 <= sy < WORLD_H:
            plan.append((tool, sx, sy))

    return plan


