            plan.append((Tool.COALPOWER, px, sy - 1))

        # Zones above and below road
        # Above zones: centered at sy-4 (zone occupies sy-6 to sy-2, road at sy)
        # Below zones: centered at sy+4 (zone occupies sy+2 to sy+6, road at sy)

        for x in range(8, 113, 6):
            # Alternate zone types: RES, COM, IND
            zone_idx = (x // 6) % 3
            if zone_idx == 0:
                zt = Tool.RESIDENTIAL
            elif zone_idx == 1:
