            else:
                zt = Tool.INDUSTRIAL

            # Above
            yy_above = sy - 4
            if 2 <= yy_above <= 97:
                plan.append((zt, x, yy_above))

            # Below
            yy_below = sy + 4
            if 2 <= yy_below <= 97:
                # Mirror zone type for variety
                if zone_idx == 0:
