                elif zone_idx == 1:
                    zt2 = Tool.INDUSTRIAL
                else:
                    zt2 = Tool.COMMERCIAL
                plan.append((zt2, x, yy_below))

    # Connect strips with vertical roads and wires at several x positions
    connector_xs = [10, 30, 50, 70, 90, 110]
    for cx in connector_xs:
        for y in range(min(strips), max(strips) + 1):
