                    wx = ox + c
                    if 0 <= wx < WORLD_W and 0 <= wire_y < WORLD_H:
                        plan.append((Tool.WIRE, wx, wire_y))

                # Road row
                for c in range(cols * 3 + 2):
                    rx = ox + c
                    if 0 <= rx < WORLD_W and 0 <= road_y < WORLD_H:
                        plan.append((Tool.ROAD, rx, road_y))

                # Zones above wire
                if 2 <= zone_y_above < WORLD_H - 2:
                    for i in range(cols):
                        zx = ox + 1 + i * 3
                        zi = (row * cols + i)
                        zt = zone_cycle[zi % len(zone_cycle)]
                        if 2 <= zx < WORLD_W - 2:
                            plan.append((zt, zx, zone_y_above))

                # Zones below road
                if 2 <= zone_y_below < WORLD_H - 2:
                    for i in range(cols):
                        zx = ox + 1 + i * 3
                        zi = (row * cols + i + cols)
                        zt = zone_cycle[zi % len(zone_cycle)]
                        if 2 <= zx < WORLD_W - 2:
                            plan.append((zt, zx, zone_y_below))

            # Vertical roads connecting wire rows
            for row in range(rows - 1):
                wire_y1 = oy + row * row_height * 2 + 1
                wire_y2 = oy + (row + 1) * row_height * 2
                # vertical road at left and right edge
                for vx in [ox, ox + cols * 3]:
                    if 0 <= vx < WORLD_W:
                        for vy in range(wire_y1, wire_y2 + 1):
                            if 0 <= vy < WORLD_H:
                                plan.append((Tool.WIRE, vx, vy))
                                plan.append((Tool.ROAD, vx + 1, vy))

        # Three main horizontal bands
        # Band 1: top area (cy~15)
        # Wire/road spine at y=15, zones at y=12 and y=19
        # Use a simpler structured approach

        def add_band(plan, spine_y, x_start, x_end, n_power_plants=3):
            width = x_end - x_start
            # Power plants spaced evenly
            pp_spacing = width // n_power_plants
            for i in range(n_power_plants):
                px = x_start + i * pp_spacing
                if px + 2 < WORLD_W:
                    plan.append((Tool.COALPOWER, px, spine_y))

            # Wire spine
            for x in range(x_start, x_end):
                plan.append((Tool.WIRE, x, spine_y))

            # Roads above and below
            for x in range(x_start, x_end):
                plan.append((Tool.ROAD, x, spine_y - 1))
                plan.append((Tool.ROAD, x, spine_y + 1))

            # Vertical roads every 6 tiles for connectivity
            for x in range(x_start + 3, x_end - 3, 6):
                for y in range(spine_y - 5, spine_y + 6):
                    if 0 <= y < WORLD_H:
                        plan.append((Tool.ROAD, x, y))

            # Zones above spine (centers at spine_y - 3 and spine_y - 7)
            for row_offset, row_idx in [(-3, 0), (-7, 1), (-11, 2)]:
                zy = spine_y + row_offset
                if 2 <= zy < WORLD_H - 2:
                    # Wire for this zone row
                    for x in range(x_start, x_end):
                        plan.append((Tool.WIRE, x, zy - 1))
                    for i, x in enumerate(range(x_start + 1, x_end - 1, 3)):
                        zi = row_idx * 40 + i
                        zt = zone_cycle[zi % len(zone_cycle)]
                        plan.append((zt, x, zy))

            # Zones below spine
            for row_offset, row_idx in [(3, 3), (7, 4), (11, 5)]:
                zy = spine_y + row_offset
                if 2 <= zy < WORLD_H - 2:
                    for x in range(x_start, x_end):
                        plan.append((Tool.WIRE, x, zy + 1))
                    for i, x in enumerate(range(x_start + 1, x_end - 1, 3)):
                        zi = row_idx * 40 + i
                        zt = zone_cycle[zi % len(zone_cycle)]
                        plan.append((zt, x, zy))

        # Four horizontal bands spread across map
        add_band(plan, spine_y=14, x_start=2, x_end=118, n_power_plants=4)
        add_band(plan, spine_y=38, x_start=2, x_end=118, n_power_plants=4)
        add_band(plan, spine_y=62, x_start=2, x_end=118, n_power_plants=4)
        add_band(plan, spine_y=86, x_start=2, x_end=118, n_power_plants=4)

        # Vertical connectors between bands (wire + road columns)
        for x in [10, 30, 50, 70, 90, 110]:
            for y in range(0, WORLD_H):
                plan.append((Tool.WIRE, x, y))
                if x + 1 < WORLD_W:
                    plan.append((Tool.ROAD, x + 1, y))

        # Nuclear plants at corners for extra power
        for px, py in [(2, 14), (112, 14), (2, 38), (112, 38),
                       (2, 62), (112, 62), (2, 86), (112, 86)]:
            plan.append((Tool.NUCLEARPOWER, px, py))

        # Re-affirm power plants (in case overwritten)
        for py in [14, 38, 62, 86]:
            for px in [2, 32, 62, 92]:
                plan.append((Tool.COALPOWER, px, py))

        # Fire and police stations
        for py in [14, 38, 62, 86]:
            for px in [15, 55, 95]:
                plan.append((Tool.FIRESTATION, px, py - 3))
            for px in [35, 75]:
                plan.append((Tool.POLICESTATION, px, py + 3))

        state["plan"] = plan
        state["i"] = 0

    i = state["i"]
    plan = state["plan"]
    if i >= len(plan):
        return None
    state["i"] = i + 1
    tool, x, y = plan[i]
    x = max(0, min(WORLD_W - 1, x))
    y = max(0, min(WORLD_H - 1, y))
    return (tool, x, y)

def act(obs, state):
    if "plan" not in state:
        plan = []

        # Strategy: Use Parent B's vertical spine approach (proven effective with 1296 pop)
        # but improve it by:
        # 1. Better wire connectivity between power plants and zones
        # 2. More balanced zone mix
        # 3. Services placed near zones
        # 4. Multiple neighborhoods across the map
        # 5. Connect neighborhoods with horizontal roads and wires

        def add_neighborhood(cx, cy, use_nuclear=False):
            """
            Vertical wire spine at cx.
            Power plant just above the zone area.
            Roads flanking the spine.
            Zones at cx-4 and cx+4 (with road at cx-1 and cx+1).
            """
            plant_y = max(2, cy - 14)
            if use_nuclear:
                plan.append((Tool.NUCLEARPOWER, cx, plant_y))
            else:
                plan.append((Tool.COALPOWER, cx, plant_y))

            # Wire spine from plant down through all zones
            for yy in range(plant_y, min(cy + 16, WORLD_H - 1)):
                plan.append((Tool.WIRE, cx, yy))

            # Road spines flanking wire (left and right)
            for dy in range(-13, 14):
                yy = cy + dy
                if 0 <= yy < WORLD_H:
                    plan.append((Tool.ROAD, cx - 1, yy))
                    plan.append((Tool.ROAD, cx + 1, yy))

            # Zones on both sides: cx-4 (left) and cx+4 (right)
            # Each zone is 3x3, placed by center
            left_types  = [Tool.RESIDENTIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL,
                           Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL,
                           Tool.INDUSTRIAL, Tool.RESIDENTIAL, Tool.COMMERCIAL]
            right_types = [Tool.COMMERCIAL, Tool.INDUSTRIAL, Tool.RESIDENTIAL,
                           Tool.COMMERCIAL, Tool.RESIDENTIAL, Tool.INDUSTRIAL,
                           Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.RESIDENTIAL]

            slot = 0
            for dy in range(-12, 13, 3):
                yy = cy + dy
                if 3 <= yy <= WORLD_H - 4:
                    plan.append((left_types[slot % len(left_types)],  cx - 4, yy))
                    plan.append((right_types[slot % len(right_types)], cx + 4, yy))
                slot += 1

            # Services near zones
            svy = cy - 14
            if 2 <= svy < WORLD_H - 1:
                plan.append((Tool.FIRESTATION,   cx - 4, svy))
                plan.append((Tool.POLICESTATION,  cx + 4, svy))

        # Four columns of neighborhoods, two rows each
        cols = [15, 42, 69, 96]
        row_ys = [28, 68]

        for col in cols:
            for row_y in row_ys:
                use_nuc = (col in [42, 69])
                add_neighborhood(col, row_y, use_nuclear=use_nuc)

        # Horizontal roads connecting neighborhoods in each row
        for row_y in row_ys:
            for i in range(len(cols) - 1):
                x0 = cols[i] + 2
                x1 = cols[i + 1] - 2
                for x in range(x0, x1 + 1):
                    plan.append((Tool.ROAD, x, row_y))

        # Vertical roads connecting top and bottom rows for each column
        for col in cols:
            for y in range(42, 55):
                plan.append((Tool.ROAD, col - 1, y))
                plan.append((Tool.ROAD, col + 1, y))

        # Horizontal wire bus at top (y=13) connecting all column spines
        for x in range(cols[0], cols[-1] + 1):
            plan.append((Tool.WIRE, x, 13))

        # Horizontal wire bus at bottom (y=53) connecting all column spines
        for x in range(cols[0], cols[-1] + 1):
            plan.append((Tool.WIRE, x, 53))

        # Connect each column's plant to top bus
        for col in cols:
            # top plant_y = 28-14 = 14, bus at 13
            for y in range(13, 16):
                plan.append((Tool.WIRE, col, y))
            # bottom plant_y = 68-14 = 54, bus at 53
            for y in range(53, 56):
                plan.append((Tool.WIRE, col, y))

        # Vertical wire connecting top bus to bottom bus on leftmost and rightmost cols
        for y in range(13, 54):
            plan.append((Tool.WIRE, cols[0], y))
            plan.append((Tool.WIRE, cols[-1], y))

        # Extra residential zones in gaps between columns at midpoints
        mid_cols = [(cols[i] + cols[i+1]) // 2 for i in range(len(cols)-1)]
        for mc in mid_cols:
            for row_y in row_ys:
                for dy in [-6, -3, 0, 3, 6]:
                    yy = row_y + dy
                    if 3 <= yy <= WORLD_H - 4:
                        plan.append((Tool.RESIDENTIAL, mc, yy))
                # Road access for mid-column zones
                for dy in range(-8, 9):
                    yy = row_y + dy
                    if 0 <= yy < WORLD_H:
                        plan.append((Tool.ROAD, mc - 1, yy))
                        plan.append((Tool.ROAD, mc + 1, yy))
                # Wire for power to mid zones
                for dy in range(-8, 9):
                    yy = row_y + dy
                    if 0 <= yy < WORLD_H:
                        plan.append((Tool.WIRE, mc, yy))
                # Connect mid wire to horizontal bus
                for x in range(min(mc, cols[0]), max(mc, cols[0]) + 1):
                    plan.append((Tool.WIRE, x, 13))
                    plan.append((Tool.WIRE, x, 53))

        # Additional fill zones between rows
        for col in cols:
            for yy in [48, 50]:
                if 3 <= yy <= WORLD_H - 4:
                    plan.append((Tool.RESIDENTIAL, col - 4, yy))
                    plan.append((Tool.RESIDENTIAL, col + 4, yy))

        # Stadium near center for happiness
        plan.append((Tool.STADIUM, 54, 48))
        for x in range(50, 59):
            plan.append((Tool.ROAD, x, 52))
        for x in range(50, 59):
            plan.append((Tool.WIRE, x, 44))
        for y in range(44, 53):
            plan.append((Tool.WIRE, 54, y))

        # Connect stadium wire to nearest bus
        for x in range(42, 55):
            plan.append((Tool.WIRE, x, 44))

        state["plan"] = plan
        state["i"] = 0

    i = state["i"]
    plan = state["plan"]
    if i >= len(plan):
        return None
    state["i"] = i + 1
    tool, x, y = plan[i]
    x = int(max(0, min(WORLD_W - 1, x)))
    y = int(max(0, min(WORLD_H - 1, y)))
    return (tool, x, y)
